import{_ as t,o as a,c as n,a2 as s}from"./chunks/framework.BGlkWkwp.js";const m=JSON.parse('{"title":"Patterns","description":"","frontmatter":{},"headers":[],"relativePath":"patterns/index.md","filePath":"patterns/README.md"}'),o={name:"patterns/index.md"};function i(r,e,h,l,p,c){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="patterns" tabindex="-1">Patterns <a class="header-anchor" href="#patterns" aria-label="Permalink to &quot;Patterns&quot;">​</a></h1><p>A pattern is a shape of screen that comes back in every drawing application: a form in a modal, a menu, a list with actions, a panel, a settings page, the workbench. Each page below says which components make it, the few rules that hold it together, and shows it working.</p><ul><li><a href="./modal-form">A modal with a form</a>: a task that stops the work, with fields, a check and one primary action.</li><li><a href="./menu">A menu</a>: actions behind a button, on an item, and in the bar of the application.</li><li><a href="./list">A list with actions</a>: items to find, select, act on and page through, and the empty list.</li><li><a href="./panel">A panel</a>: a side of the screen with a head, groups that reach the edges and a foot.</li><li><a href="./settings">A settings page</a>: tabs, groups of settings and a list of members.</li><li><a href="./workbench">A workbench</a>: the shell with the layers, the stage, the tools and the inspector.</li></ul><p>The patterns use only the <a href="./../components/README">components</a> and the <a href="./../workbench/README">workbench parts</a>; nothing on these pages is a component of its own.</p>',4)])])}const f=t(o,[["render",i]]);export{m as __pageData,f as default};
